export const AGENT_STATUSES=['starting','running','waiting','completed','stopped','failed','interrupted','disconnected'];
export const SETTLED_STATUSES=['completed','stopped','failed','interrupted','disconnected'];
export const CORE_EVENT_TYPES=[
'run.status',
'agent.status',
'message.delta',
'message.complete',
'tool.call',
'approval.requested',
'approval.resolved',
'draft.begin',
'draft.update',
'draft.cancel',
'draft.complete',
'artifact.saved',
'navigation',
];
const MAX_ID=256;
const MAX_AT=64;
const TYPE=/^[a-z][a-z0-9-]*(?:\.[a-z0-9_-]+)+$/;
const ID=/^[^\s\u0000-\u001f\u007f]+$/;
export const isCoreType=(type)=>CORE_EVENT_TYPES.includes(type);
export const isExtensionType=(type)=>type.startsWith('x.')&&type.split('.').length>=3;
export const isAgentStatus=(value)=>AGENT_STATUSES.includes(value);
export const isSettled=(status)=>SETTLED_STATUSES.includes(status);
export function isRecord(value){
if(typeof value!=='object'||value===null||Array.isArray(value))
return false;
const proto=Object.getPrototypeOf(value);
return proto===Object.prototype||proto===null;
}
const isId=(value)=>typeof value==='string'&&value.length>0&&value.length<=MAX_ID&&ID.test(value);
export function parseAgentEvent(value){
if(!isRecord(value)||value.v!==1)
return null;
const{seq,at,runId,agentId,parentAgentId,type,data}=value;
if(typeof seq!=='number'||!Number.isSafeInteger(seq)||seq<1)
return null;
if(typeof at!=='string'||at.length===0||at.length>MAX_AT)
return null;
if(!isId(runId)||!isId(agentId))
return null;
if(parentAgentId!==null&&parentAgentId!==undefined&&!isId(parentAgentId))
return null;
if(typeof type!=='string'||type.length>96||!TYPE.test(type))
return null;
if(!isRecord(data))
return null;
return{v:1,seq,at,runId,agentId,parentAgentId:parentAgentId??null,type,data};
}
